"""Render the recorded comparison without calling a model or external website."""
import html
import json
from pathlib import Path

out = Path(__file__).resolve().parents[2] / 'docs/evaluations/kundali-guidance-2026-09-18'
engine = json.loads((out / 'engine.json').read_text())
platform = {
    'sample-a': {'summary': 'The published report ranks Conventional first and Enterprising second. It recommends structured, detailed work and leadership-oriented roles, then suggests researching options and speaking with people in those fields.', 'limitation': 'It also discourages broad career categories. Its occupation catalogue includes fields discouraged elsewhere. This is a natal career report, not a September 2026 job-switch consultation.', 'pages': 'Birth/positions: PDF pages 16–17; interpretation: 8–9; research actions: 18–19.'},
    'sample-b': {'summary': 'The published report favours Conventional and Enterprising work: organised tasks, detail, management and persuasion. It encourages exploring several career choices and researching their daily work.', 'limitation': 'Its avoid list includes science, technology and creative work, yet parts of its occupation catalogue conflict with those exclusions. GPT suggests technology-related paths for this same chart. Neither recommendation is treated as established aptitude.', 'pages': 'Birth/positions: PDF pages 4–6; interpretation: 8–10. Report dated 22 April 2019.'},
}
observations = {
    'sample-a': 'Our reading links work with other people and flags workload/structure. GPT gives richer Saturn/service prose but introduces specific occupations and a financial-buffer rule despite only a general question. The platform gives career-type labels. Our new actions stay conditional on actual circumstances.',
    'sample-b': 'Before: the engine advised growth in the current job without knowing whether there was a current job. Now: it asks for context and flags uncertain support. GPT introduces technology/communication occupations while the published platform report discourages technology. This is a substantive interpretive disagreement, not a calculation mismatch.',
    'synthetic-adult': 'Before: the same growth-in-current-role template appeared. Now: selecting job switch changes the checklist to reasons for change and verifying the role/workload, while keeping the same underlying chart facts. GPT is more specific but also claims compensation support and over-promising risks that our current reviewed rules do not establish.',
    'synthetic-minor': 'Now: the exam checklist addresses a parent and asks for observation and collaborative practice. Adult-only topics are gated. GPT infers worry, daydreaming and screen-time concerns and prescribes study-block lengths; those are unsupported assumptions about this fictional child. There is no external platform report for this fixture.',
}
# Transcribed factual longitude rows from the two linked official sample PDFs.
positions = {
    'sample-a': {'asc': (5, '24-39-11'), 'sun': (11, '27-29-07'), 'moon': (5, '15-45-05'), 'mars': (11, '09-55-29'), 'mercury': (11, '02-58-41'), 'jupiter': (3, '05-49-24'), 'venus': (10, '22-28-03'), 'saturn': (4, '14-11-58'), 'rahu': (4, '22-19-55'), 'ketu': (10, '22-19-55')},
    'sample-b': {'asc': (5, '03-21-29'), 'sun': (4, '20-31-09'), 'moon': (0, '03-43-54'), 'mars': (6, '27-42-42'), 'mercury': (5, '17-27-01'), 'jupiter': (6, '13-32-22'), 'venus': (4, '05-22-42'), 'saturn': (5, '26-42-13'), 'rahu': (2, '16-22-53'), 'ketu': (8, '16-22-53')},
}
checks = []
for case in engine['cases']:
    case['gpt'] = json.loads((out / f"gpt-{case['id']}.json").read_text())
    expected = {'id': case['id'], 'asOf': case['asOf'], 'question': case['reading']['guidance']['question']['en'], 'purpose': case['purposeId'], 'facts': case['facts']}
    if json.loads(case['gpt']['request']['input']) != expected:
        raise ValueError(f'Stale GPT facts for {case["id"]}; do not label this a matched comparison')
    case['platform'] = platform.get(case['id'])
    case['observation'] = observations[case['id']]
    rows = []
    for name, (sign, dms) in positions.get(case['id'], {}).items():
        deg, minute, second = map(int, dms.split('-'))
        reference = sign * 30 + deg + minute / 60 + second / 3600
        actual = case['facts']['ascendant']['longitude'] if name == 'asc' else next(p['siderealLongitude'] for p in case['facts']['planets'] if p['graha'] == name)
        rows.append({'body': name, 'referenceLongitude': reference, 'engineLongitude': actual, 'deltaArcminutes': abs((actual - reference + 180) % 360 - 180) * 60, 'signAgrees': int(actual // 30) == sign})
    case['chartCheck'] = rows
    if rows:
        checks.append({'caseId': case['id'], 'source': case['source'], 'rows': rows})
(out / 'chart-check.json').write_text(json.dumps(checks, indent=2) + '\n')
data = json.dumps(engine, ensure_ascii=False).replace('</', '<\\/')
page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kundali guidance · evidence comparison</title>
<style>
:root{color-scheme:light;--ink:#302b26;--muted:#756b60;--line:#ddd4c6;--gold:#985728;--paper:#faf6ef}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 system-ui,sans-serif}main{max-width:1420px;margin:auto;padding:36px 32px}h1,h2,h3{line-height:1.2}h1{font:500 clamp(32px,4vw,51px)/1.15 Georgia,serif;margin:12px 0}h2{font:500 25px/1.25 Georgia,serif}h3{font-size:17px}.eyebrow,small{font-size:12px;color:var(--muted)}.eyebrow{text-transform:uppercase;letter-spacing:2px}.intro{max-width:950px}.notice{border-left:3px solid var(--gold);padding:12px 18px;background:#eee6d7}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}button{font:inherit;border:1px solid var(--line);padding:10px 16px;border-radius:30px;color:var(--ink);background:#fff;cursor:pointer}button[aria-selected=true]{background:#433c31;color:#fff}.meta{margin:16px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:start}.panel{background:#fffdf9;border:1px solid var(--line);padding:24px;border-radius:18px}.ours{border-top:4px solid var(--gold)}.tag{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--gold)}.insight{border-top:1px solid var(--line);margin-top:18px;padding-top:4px}.actions{padding-left:23px}.actions li{margin:10px 0}.raw{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}.note{font-size:13px;color:var(--muted)}summary{cursor:pointer;font-weight:600;padding:10px 0}details{border-top:1px solid var(--line);margin-top:18px}pre{overflow:auto;max-height:480px;font-size:12px}a{color:#955225}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid var(--line);text-align:left;padding:8px}.scroll{overflow:auto}.takeaway{margin-top:22px;padding:18px 24px;background:#eae5d8;border-radius:12px}footer{margin:30px 0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:28px}.stat{display:inline-block;margin:8px 20px 8px 0}.stat b{display:block;font:28px Georgia,serif}@media(max-width:980px){.grid{grid-template-columns:1fr}.columns{grid-template-columns:1fr}main{padding:24px 16px}.panel{padding:20px}}
</style><main><div class="eyebrow">Vedansh · 18 September 2026 · implementation evaluation</div><h1>Less chart decoding.<br>More useful next steps.</h1><p class="intro">Four birth profiles, the previous engine, the new deterministic reading, and actual GPT responses. Two profiles also match official public AstroSage sample reports.</p><div class="notice"><b>What this establishes:</b> differences in language, reasoning and actionability. It does not establish predictive accuracy. GPT was given our raw chart calculations; the competitor reports are historical natal career reports, not fresh answers to the same dated question.</div><div class="tabs" id="tabs" role="tablist" aria-label="Comparison profiles"></div><div id="content"></div><section class="panel" style="margin-top:28px"><h2>How the app computes this</h2><div class="columns"><div><ol><li><b>Calculate facts:</b> birth instant, location → Lahiri sidereal positions, whole-sign houses, house lords, dignity and current periods.</li><li><b>Gather topic evidence:</b> the existing purpose registry selects houses and karakas. Rules produce support, resistance or qualifying context with basis IDs.</li><li><b>Compose meaning:</b> group house facts into everyday themes, keep contradictions, and show the main theme plus a caution. The lord's actual destination supplies the connection.</li><li><b>Choose practical steps:</b> explicit question context selects reviewed bilingual suggestions. These are editorial prompts, not outcomes inferred from planets.</li><li><b>Preserve detail:</b> expandable evidence and the full export retain factors, sources, dates and the selected question.</li></ol></div><div><h3>What remains limited</h3><p>Theme copy is still a small phrase library. It cannot learn the person's goals, experience, constraints or actual offers from a birth chart. Karaka factors remain in the full analysis; the new visible themes currently group house-lord and occupant evidence. The headline is not a complete chart adjudication.</p><p>Published rule sources still require the existing release review. Agreement counts and theme tones are internal rule labels, not probabilities. Timing relevance does not establish a favourable period.</p><p>GPT is a single pinned API run per fixture, with no tools and no access to our composed answer. It tests writing from shared facts, not an independent astronomical engine or the consumer ChatGPT app.</p></div></div></section><section class="panel" style="margin-top:24px"><h2>Verification & reproduction</h2><p>TypeScript, 465 engine tests, 47 Ask tests and 10 focused screen tests passed. The iOS production JS bundle exported. Data checks: 108 passed, one inherited launch-byte-budget failure (baseline 7,131,688 bytes; current 7,131,753; limit 7,000,000).</p><p id="native-status">Full clean-state iOS simulator smoke passed on 21 September using the existing native debug shell and current JavaScript. <a href="screenshots/prashna-guidance.png">Guidance screenshot</a> · <a href="screenshots/prashna-actions.png">Checklist screenshot</a> · <a href="screenshots/prashna-evidence.png">Expanded evidence</a> · <a href="native-smoke.log">Execution log</a>. Android and physical devices remain untested.</p><p>Reproduce from <code>mobile/</code>: <code>npx tsx scripts/compare-prashna.mts</code>, optionally <code>python3 scripts/compare-prashna-gpt.py --run-gpt</code>, then <code>python3 scripts/render-prashna-comparison.py</code>. GPT calls require an API key and reuse existing response files. The app never calls GPT.</p><p><a href="engine.json">Full engine output</a> · <a href="gpt-input.json">GPT input facts</a> · <a href="chart-check.json">Position comparison</a> · <a href="README.md">Review notes</a></p></section><footer class="note">Public sample data and fictional fixtures only. No claim of a private Astrotalk consultation. No accounts, purchases or messages were sent.</footer></main>
<script>const data=__DATA__;const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let chosen=0,readingLanguage='en';const str=x=>esc(x[readingLanguage]);
function render(){const c=data.cases[chosen],g=c.reading.guidance;document.getElementById('tabs').innerHTML=data.cases.map((x,i)=>`<button role="tab" aria-selected="${i===chosen}" onclick="chosen=${i};render()">${esc(x.label)}</button>`).join('');const max=c.chartCheck.length?Math.max(...c.chartCheck.map(r=>r.deltaArcminutes)).toFixed(2):null;
document.getElementById('content').innerHTML=`<div class="meta"><b>${esc(c.localBirth)}</b><br><span class="note">Question: ${esc(g.question.en)} · As of 18 Sep 2026, 12:00 IST · ${esc(c.facts.age)}</span></div><div class="grid"><article class="panel ours"><div class="tag">Our engine · actual output</div><div style="margin-top:12px"><button onclick="readingLanguage=readingLanguage==='en'?'hi':'en';render()">${readingLanguage==='en'?'हिन्दी में देखें':'Read in English'}</button></div><h2>${str(g.title)}</h2>${g.parentNote?`<p class="notice">${str(g.parentNote)}</p>`:''}${g.insights.map(i=>`<div class="insight"><h3>${str(i.title)}</h3><p>${str(i.meaning)}</p></div>`).join('')}<h3>${readingLanguage==='en'?'A practical plan':'आप क्या कर सकते हैं'}</h3><small>Editorial suggestions · not inferred personal facts</small><ol class="actions">${g.actions.map(a=>`<li>${str(a.text)}</li>`).join('')}</ol><p class="note">${str(g.caution)}</p><details><summary>Related periods & evidence</summary><p>${str(g.timing.text)}</p>${g.timing.windowIds.map(id=>{const w=c.reading.analysis.windows.find(w=>w.id===id);return `<p>${esc(w.labelEn)}<br>${esc(w.textEn)}</p>`}).join('')}<pre>${esc(JSON.stringify(g.insights.map(i=>({theme:i.id,factorIds:i.factorIds,basis:i.basis,source:i.source})),null,2))}</pre></details><details><summary>Before this change</summary><h3>${esc(c.before.title)}</h3><p>${esc(c.before.summary)}</p><ul>${c.before.actions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><small>Baseline ${esc(data.baselineCommit)} · same birth profile and date</small></details></article><article class="panel"><div class="tag">GPT · actual API response</div><h2>An independent reading<br>from the same facts</h2><p class="note">${esc(c.gpt.returnedModel)} · ${c.gpt.seconds}s · ${esc(c.gpt.status)}<br>English only; the response is displayed verbatim.</p><div class="raw">${esc(c.gpt.text)}</div><details><summary>Request, provenance & usage</summary><pre>${esc(JSON.stringify({model:c.gpt.returnedModel,responseId:c.gpt.responseId,usage:c.gpt.usage,instructions:c.gpt.request.instructions},null,2))}</pre><a href="gpt-${c.id}.json">Full recorded request and response</a></details></article><article class="panel"><div class="tag">AstroSage · published sample</div><h2>${c.platform?'Matched birth profile':'No matched report'}</h2>${c.platform?`<p>${esc(c.platform.summary)}</p><p>${esc(c.platform.limitation)}</p><p class="note">${esc(c.platform.pages)}</p><a href="${esc(c.source)}" target="_blank" rel="noreferrer">Read the original sample PDF ↗</a><details><summary>Do the chart calculations match?</summary><p>All ten checked sign assignments agree (ascendant + nine grahas). Largest angular difference: ${max} arcminutes. This comparison does not cover exact dasha boundaries or validate interpretations.</p><div class="scroll"><table><tr><th>Body</th><th>Difference (arcmin)</th></tr>${c.chartCheck.map(r=>`<tr><td>${esc(r.body)}</td><td>${r.deltaArcminutes.toFixed(3)}</td></tr>`).join('')}</table></div></details>`:`<p>No platform answer was obtained for this synthetic profile. We do not invent what an astrologer would have said.</p><p class="note">The free-form report attempt redirected to a consultation sign-in flow. No account or paid consultation was created.</p>`}<details><summary>All nine purpose gates</summary><table><tr><th>Topic</th><th>Result</th></tr>${c.matrix.map(r=>`<tr><td>${esc(r.purposeId)}</td><td>${r.gated?'Age-gated':'Reading available'}</td></tr>`).join('')}</table></details></article></div><div class="takeaway"><b>Reviewer's observation</b><p>${esc(c.observation)}</p></div>`;}
render();</script></html>'''.replace('__DATA__', data)
(out / 'comparison.html').write_text(page)
print('Rendered', out / 'comparison.html')
print('Chart checks:', [(c['caseId'], max(r['deltaArcminutes'] for r in c['rows']), all(r['signAgrees'] for r in c['rows'])) for c in checks])
